require_once __DIR__.'/../includes/auth.php';auth_require();require_once __DIR__.'/../includes/listing.php';$error='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{fx_post($_POST);redirect(BASE_URL.'modules/fx.php');}catch(Throwable $e){http_response_code(in_array($e->getCode(),[403,429],true)?$e->getCode():422);$error=public_error($e);}
$sorts=['newest'=>['id DESC','Newest first','تازه‌ترین اول'],'oldest'=>['id ASC','Oldest first','قدیمی‌ترین اول']];[$list,$history]=listing_query($pdo,'SELECT * FROM fx_documents WHERE shop_id=?',[shop_id()],$sorts);$pageTitle=__t('Currency exchange & settlement','تبدیل ارز و تسویه','د اسعارو تبادله او تصفیه');require __DIR__.'/../includes/header.php';
function fx_common(string $kind): void {echo csrf_field().'<input name="action" type="hidden" value="approve_fx"><input name="kind" type="hidden" value="'.$kind.'"><input name="request_key" type="hidden" value="'.bin2hex(random_bytes(16)).'">';}
function fx_debts(): void {global $pdo;$q=$pdo->prepare('SELECT id,customer_name,remaining_amount,currency_code,debt_type FROM debts WHERE shop_id=? AND remaining_amount>0 ORDER BY id DESC LIMIT 250');$q->execute([shop_id()]);?><label><?= __t('Receivable / payable','طلب یا بدهی','طلب یا پور') ?><select class="form-control" name="debt_id" required><?php foreach($q->fetchAll() as $d):?><option value="<?= (int)$d['id'] ?>"><?= sanitize('#'.$d['id'].' · '.$d['customer_name'].' · '.$d['remaining_amount'].' '.$d['currency_code'].' · '.($d['debt_type']==='payable'?__t('Payable','بدهی','پور'):__t('Receivable','طلب','طلب'))) ?></option><?php endforeach ?></select></label><?php }
function fx_amounts(string $first,string $second): void {?><div class="form-grid"><label><?= $first ?><input class="form-control" name="source_amount" type="number" min="0.01" step="0.01" required></label><label><?= $second ?><input class="form-control" name="target_amount" type="number" min="0.01" step="0.01" required></label><label><?= __t('Date','تاریخ','نېټه') ?><input class="form-control" name="document_date" type="date" value="<?= date('Y-m-d') ?>" required></label></div><label><?= __t('Exchange receipt / agreed rate reference','رسید تبدیل ارز یا مرجع توافق نرخ','د تبادلې رسید یا د نرخ مرجع') ?><textarea class="form-control" name="reason" minlength="3" maxlength="500" required></textarea></label><button class="btn btn-primary"><?= __t('Approve documented settlement','تأیید سند و تسویه','سند او تصفیه تایید') ?></button><?php }
?>
<h1><?= sanitize($pageTitle) ?></h1><p><?= __t('Record both actual amounts and the exchange agreement. Each currency keeps its own ledger. Exchange-clearing positions are shown separately; no automatic market valuation or exchange gain is invented. Receipt allocation does not collect cash twice.','هر دو مبلغ واقعی و مرجع توافق تبدیل ارز را ثبت کنید. هر ارز دفتر جدا دارد. حساب واسطهٔ تبدیل ارز جدا نشان داده می‌شود؛ ارزش بازار یا مفاد تبدیل به شکل حدسی محاسبه نمی‌شود. تخصیص رسید، پول را دوباره دریافت نمی‌کند.','دواړه حقیقي مبلغونه او د تبادلې موافقه ولیکئ؛ هر اسعار خپل دفتر لري.') ?></p><?php if($error):?><p class="alert alert-danger" role="alert"><?= sanitize($error) ?></p><?php endif ?>
<div class="branch-grid">
<?php if(domain_can('treasury.exchange')):?><section class="card modern-form"><h2><?= __t('Exchange cash / bank funds','تبدیل پول صندوق یا بانک','د نغدو یا بانک پیسې تبادله') ?></h2><form method="post"><?php fx_common('exchange');funds_select('source_account');?><label><?= __t('Receiving account in another currency','حساب گیرنده با ارز متفاوت','په بل اسعارو د ترلاسه حساب') ?><?php $q=$pdo->prepare("SELECT id,name,currency_code FROM fund_accounts WHERE shop_id=? AND status='active' ORDER BY name,id");$q->execute([shop_id()]);?><select class="form-control" name="destination_account" required><?php foreach($q->fetchAll() as $a):?><option value="<?= (int)$a['id'] ?>"><?= sanitize($a['name'].' · '.$a['currency_code']) ?></option><?php endforeach ?></select></label><?php fx_amounts(__t('Amount paid from source account','مبلغ پرداخت از حساب اول','له لومړي حساب ورکړه'),__t('Amount received in destination account','مبلغ دریافت در حساب گیرنده','په ترلاسه حساب کې مبلغ'));?></form></section><?php endif ?>
<?php if(domain_can('treasury.fx_settle')):?><section class="card modern-form"><h2><?= __t('Settle using another currency','تسویه با ارز متفاوت','په بل اسعارو تصفیه') ?></h2><form method="post"><?php fx_common('debt');fx_debts();funds_select('source_account');fx_amounts(__t('Actual amount received / paid in account currency','مبلغ واقعی دریافت یا پرداخت به ارز حساب','په حساب اسعارو حقیقي ورکړه یا رسید'),__t('Amount applied in invoice currency','مبلغ تسویه به ارز بل','په بل اسعارو تصفیه شوې پیسې'));?></form></section>
<section class="card modern-form"><h2><?= __t('Allocate an existing foreign receipt','تخصیص رسید موجود با ارز متفاوت','د شته بهرني رسید تخصیص') ?></h2><form method="post"><?php fx_common('receipt');fx_debts();?><label><?= __t('Original foreign sale receipt','رسید اصلی فروش با ارز متفاوت','د بهرني پلور اصلي رسید') ?><select class="form-control" name="receipt_id" required><?php $q=$pdo->prepare("SELECT t.*,s.invoice_no FROM fund_transactions t JOIN sales s ON s.id=t.source_id AND s.shop_id=t.shop_id WHERE t.shop_id=? AND t.source_type='sale' AND t.direction='in' AND t.currency_code<>s.currency_code ORDER BY t.id DESC LIMIT 250");$q->execute([shop_id()]);foreach($q->fetchAll() as $r):?><option value="<?= (int)$r['id'] ?>"><?= sanitize($r['reference'].' · '.$r['invoice_no'].' · '.$r['amount'].' '.$r['currency_code']) ?></option><?php endforeach ?></select></label><?php fx_amounts(__t('Receipt amount to allocate','مبلغ رسید برای تخصیص','د تخصیص رسید مبلغ'),__t('Amount applied in invoice currency','مبلغ تسویه به ارز بل','په بل اسعارو تصفیه شوې پیسې'));?></form></section><?php endif ?>
</div>
<section class="card modern-form table-responsive"><h2><?= __t('Exchange documents','اسناد تبدیل ارز','د تبادلې سندونه') ?></h2><table class="table"><thead><tr><?php foreach([__t('Date','تاریخ','نېټه'),__t('Type','نوع سند','ډول'),__t('Account currency amount','مبلغ ارز حساب','د حساب اسعارو مبلغ'),__t('Invoice / receiving amount','مبلغ بل یا حساب گیرنده','د بل یا ترلاسه مبلغ'),__t('Agreed rate','نرخ توافق‌شده','موافقه شوی نرخ'),__t('Reference','مرجع','مرجع')] as $h):?><th><?= $h ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($history as $r):?><tr><td><?= sanitize($r['document_date']) ?></td><td><?= $r['kind']==='exchange'?__t('Exchange','تبدیل ارز','تبادله'):($r['kind']==='debt'?__t('Settlement','تسویه','تصفیه'):__t('Receipt allocation','تخصیص رسید','د رسید تخصیص')) ?></td><td><?= sanitize($r['source_amount'].' '.$r['source_currency']) ?></td><td><?= sanitize($r['target_amount'].' '.$r['target_currency']) ?></td><td><?= sanitize(dec_div($r['target_amount'],$r['source_amount'],8)) ?></td><td><?= sanitize($r['reason']) ?></td></tr><?php endforeach ?></tbody></table></section>
<?php listing_controls_form($list);listing_footer($list);require __DIR__.'/../includes/footer.php'; ?>
